import{K as r,a as i,c,b as a,k as t,q as n,ac as h}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Excel 打印、导出与工作簿交付","description":"设置 Excel 打印区域、纸张方向、缩放、重复标题、分页和页眉，检查 CSV 与 PDF 导出、公式保留和外部链接。","frontmatter":{"title":"Excel 打印、导出与工作簿交付","description":"设置 Excel 打印区域、纸张方向、缩放、重复标题、分页和页眉，检查 CSV 与 PDF 导出、公式保留和外部链接。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"设置 Excel 打印区域、纸张方向、缩放、重复标题、分页和页眉，检查 CSV 与 PDF 导出、公式保留和外部链接。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Excel 进阶分析：数据模型、目标求解与方案比较","link":"/tools/office/excel/analysis"},"next":{"text":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 进阶分析：数据模型、目标求解与方案比较","link":"/tools/office/excel/analysis"},"next":{"text":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project"}},"headers":[],"relativePath":"tools/office/excel/printing.md","filePath":"tools/office/excel/printing.md"}'),s={name:"tools/office/excel/printing.md"},k=Object.assign(s,{setup(d){const o={path:"/tools/office/excel/printing",app:"Excel",title:"宽表分多页打印仍然可读",steps:[{tab:"页面布局",command:"打印区域",setting:"区域：需要交付的列与行",anchor:"walkthrough-1"},{tab:"页面布局",command:"缩放",setting:"宽度：1 页；高度：自动；方向：横向",anchor:"walkthrough-2"},{tab:"页面布局",command:"打印标题",setting:"顶端标题行：$1:$1；逐页核对",anchor:"walkthrough-3"}]};return(p,e)=>{const l=r("OfficeGuide");return i(),c("div",null,[e[0]||(e[0]=a("h1",{id:"excel-打印、导出与工作簿交付",tabindex:"-1"},[t("Excel 打印、导出与工作簿交付 "),a("a",{class:"header-anchor",href:"#excel-打印、导出与工作簿交付","aria-label":'Permalink to "Excel 打印、导出与工作簿交付"'},"​")],-1)),e[1]||(e[1]=a("p",null,[t("屏幕里看起来完整的表格，打印时可能被切成十几页。先决定交付者要继续计算、查看固定页面，还是导入其他系统，再选择 "),a("code",null,".xlsx"),t("、PDF 或 CSV。")],-1)),n(l,{guide:o}),e[2]||(e[2]=h('<h2 id="area" tabindex="-1">设置打印区域 <a class="header-anchor" href="#area" aria-label="Permalink to &quot;设置打印区域 {#area}&quot;">​</a></h2><p>在<a href="/tools/office/excel/start">订单练习表</a>中选中 A1:H9，选择“页面布局 → 打印区域 → 设置打印区域”。区域外的辅助列和参数不会因此从工作簿删除，只是不进入该打印区域；外发源文件时仍需要检查它们是否适合分享。</p><p>进入“文件 → 打印”查看预览，确认打印活动工作表、整个工作簿还是选定区域。以前设置过打印区域的文件可能只打印局部内容，数据追加后要重新检查范围。</p><h2 id="scale" tabindex="-1">纸张、方向和缩放 <a class="header-anchor" href="#scale" aria-label="Permalink to &quot;纸张、方向和缩放 {#scale}&quot;">​</a></h2><p>宽表通常可试横向纸张，再调整页边距、列宽和长文本换行。“将所有列调整为一页”适合横向略宽但纵向较长的表格；设置宽度一页、高度自动，通常比把整个工作表压成一页更可读。</p><p>不要只以页数少为目标。缩放后字体过小，应拆分报表、减少非必要列或调整版式。合并单元格可能影响自动行高和分页，明细数据尽量避免合并。</p><h2 id="titles" tabindex="-1">重复标题与分页 <a class="header-anchor" href="#titles" aria-label="Permalink to &quot;重复标题与分页 {#titles}&quot;">​</a></h2><p>在“页面布局 → 打印标题”设置顶端标题行为 <code>$1:$1</code>，使每页重复字段名。冻结首行只影响屏幕滚动，不会自动变成打印标题。需要每页重复左边的标识列时也可设置对应区域。</p><p>使用“视图 → 分页预览”观察横向和纵向分页位置，必要时调整手动分页。大量空白页可能来自过大的打印区域、远处残留格式或多余对象；先定位原因，不随意删除整列来碰运气。</p><p>页眉页脚可加入报表名、统计区间和“第几页/共几页”，不要在数据末尾手写页码。页码字段随打印变化，工作表中的普通文字不会自动更新。</p><h2 id="deliver" tabindex="-1">选择交付格式 <a class="header-anchor" href="#deliver" aria-label="Permalink to &quot;选择交付格式 {#deliver}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格式</th><th>适合情况</th><th>交付前检查</th></tr></thead><tbody><tr><td>XLSX</td><td>对方继续筛选、计算或分析</td><td>公式、数据验证、隐藏表、外部链接、版本兼容</td></tr><tr><td>PDF</td><td>审阅固定版式、归档打印</td><td>所有页的表头、字体、单位和分页</td></tr><tr><td>CSV</td><td>给其他系统导入纯表数据</td><td>编码、分隔符、字段名、日期和编号类型</td></tr></tbody></table><p>CSV 不保留多工作表、图表和公式计算能力。需要交付纯数据时先另存副本，再导出指定工作表；重新导入检查首行、末行和含逗号、换行、引号的字段。UTF-8 编码是否符合对方系统要求应明确确认。</p><h2 id="snapshot" tabindex="-1">固定结果与可刷新结果 <a class="header-anchor" href="#snapshot" aria-label="Permalink to &quot;固定结果与可刷新结果 {#snapshot}&quot;">​</a></h2><p>历史月报希望保持当时结果，可以交付 PDF 和独立值快照，同时保留原始可计算工作簿。另存副本后粘贴为值会丢失公式，应在文件名和说明中标记“值快照”。不要以删除公式的方式代替解释口径。</p><p>可刷新工作簿还需要数据源路径、权限、查询步骤和刷新顺序。源文件在你电脑上存在，不代表对方能访问。交付说明至少写明数据截止日期、是否能刷新，以及刷新后哪些结果会改变。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>把练习表临时复制扩展到三页，在每页重复首行，设置宽度一页、高度自动，导出 PDF。逐页确认没有单独被挤出去的金额列，也没有文字被固定行高截断。检查完成后使用原八条数据继续后续练习。</p><h2 id="walkthrough" tabindex="-1">图示跟做：宽表分多页打印仍然可读 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：宽表分多页打印仍然可读 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先排除辅助计算区域 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先排除辅助计算区域 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：页面布局 → 打印区域。</strong></p><p>在订单副本选择需要交付的明细列与标题，点击“页面布局 → 打印区域 → 设置打印区域”。不要把远处临时计算格一起框进来。进入打印预览，看总页数是否合理；若多出几十页，检查远处格式残留和已有打印区域。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：让宽度受控而高度可分页 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：让宽度受控而高度可分页 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：页面布局 → 缩放。</strong></p><p>对于宽表设置横向，根据实际字段数量调整列宽，缩放宽度为 1 页、高度自动。避免强制整张长表塞进 1 页高，使字号缩到无法阅读。纸张大小必须与目标打印或 PDF 页面一致，调整后重新检查长产品名是否被截断。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：让每一页都能理解字段 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：让每一页都能理解字段 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：页面布局 → 打印标题。</strong></p><p>打开打印标题，将顶端标题行设置为 $1:$1；如果表头占两行，则按实际范围设置。预览每一页，核对表头、页码、单位和末页合计。冻结窗格只影响屏幕滚动，不会自动让打印重复表头，二者要分别设置。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>打印标题选项不可用时，检查是否在编辑单元格、是否选择了图表或多张工作表。先回到普通工作表选择一个单元格，再设置并重新预览。</p>',31))])}}});export{u as __pageData,k as default};
